class ConnectionRole(enum.Enum):
    """
    Who opened the connection. **Both peers must pass the same value.**

    This is the byte appended to the prologue. It describes the connection, not
    the caller: a core that accepts an inbound connection is the *responder*
    while still passing [`ConnectionRole::ModuleInitiated`].
"""
    
    CORE_INITIATED = 0
    """
    The core opened the connection (core = Noise initiator). Byte `1`.
"""
    
    MODULE_INITIATED = 1
    """
    The module opened the connection (module = Noise initiator). Byte `2`.
"""
    


class _UniffiFfiConverterTypeConnectionRole(_UniffiConverterRustBuffer):
    @staticmethod
    def read(buf):
        variant = buf.read_i32()
        if variant == 1:
            return ConnectionRole.CORE_INITIATED
        if variant == 2:
            return ConnectionRole.MODULE_INITIATED
        raise InternalError("Raw enum value doesn't match any cases")

    @staticmethod
    def check_lower(value):
        if value == ConnectionRole.CORE_INITIATED:
            return
        if value == ConnectionRole.MODULE_INITIATED:
            return
        raise ValueError(value)

    @staticmethod
    def write(value, buf):
        if value == ConnectionRole.CORE_INITIATED:
            buf.write_i32(1)
        if value == ConnectionRole.MODULE_INITIATED:
            buf.write_i32(2)








