class _UniffiFfiConverterString:
    @staticmethod
    def check_lower(value):
        if not isinstance(value, str):
            raise TypeError("argument must be str, not {}".format(type(value).__name__))
        return value

    @staticmethod
    def read(buf):
        size = buf.read_i32()
        if size < 0:
            raise InternalError("Unexpected negative string length")
        utf8_bytes = buf.read(size)
        return utf8_bytes.decode("utf-8")

    @staticmethod
    def write(value, buf):
        utf8_bytes = value.encode("utf-8")
        buf.write_i32(len(utf8_bytes))
        buf.write(utf8_bytes)

    @staticmethod
    def lift(buf):
        with buf.consume_with_stream() as stream:
            return stream.read(stream.remaining()).decode("utf-8")

    @staticmethod
    def lower(value):
        with _UniffiRustBuffer.alloc_with_builder() as builder:
            builder.write(value.encode("utf-8"))
            return builder.finalize()

class _UniffiFfiConverterBoolean:
    @classmethod
    def check_lower(cls, value):
        return not not value

    @classmethod
    def lower(cls, value):
        return 1 if value else 0

    @staticmethod
    def lift(value):
        return value != 0

    @classmethod
    def read(cls, buf):
        return cls.lift(buf.read_u8())

    @classmethod
    def write(cls, value, buf):
        buf.write_u8(value)



# FfiError
# We want to define each variant as a nested class that's also a subclass,
# which is tricky in Python.  To accomplish this we're going to create each
# class separately, then manually add the child classes to the base class's
# __dict__.  All of this happens in dummy class to avoid polluting the module
# namespace.
class FfiError(Exception):
    """
    The only error that crosses FFI. Mirrors C-04: `code`, `message`,
    `retriable`, plus the protocol-core specific `fatal`.
"""
    pass

_UniffiTempFfiError = FfiError

class FfiError:  # type: ignore
    """
    The only error that crosses FFI. Mirrors C-04: `code`, `message`,
    `retriable`, plus the protocol-core specific `fatal`.
"""
    
    class Protocol(_UniffiTempFfiError):
        """
        A `ProtocolError` from the core.
"""
        
        def __init__(self, code, message, fatal, retriable):
            super().__init__(", ".join([
                "code={!r}".format(code),
                "message={!r}".format(message),
                "fatal={!r}".format(fatal),
                "retriable={!r}".format(retriable),
            ]))
            self.code = code
            self.message = message
            self.fatal = fatal
            self.retriable = retriable

        def __repr__(self):
            return "FfiError.Protocol({})".format(str(self))
    _UniffiTempFfiError.Protocol = Protocol # type: ignore

FfiError = _UniffiTempFfiError # type: ignore
del _UniffiTempFfiError


class _UniffiFfiConverterTypeFfiError(_UniffiConverterRustBuffer):
    @staticmethod
    def read(buf):
        variant = buf.read_i32()
        if variant == 1:
            return FfiError.Protocol(
                _UniffiFfiConverterString.read(buf),
                _UniffiFfiConverterString.read(buf),
                _UniffiFfiConverterBoolean.read(buf),
                _UniffiFfiConverterBoolean.read(buf),
            )
        raise InternalError("Raw enum value doesn't match any cases")

    @staticmethod
    def check_lower(value):
        if isinstance(value, FfiError.Protocol):
            _UniffiFfiConverterString.check_lower(value.code)
            _UniffiFfiConverterString.check_lower(value.message)
            _UniffiFfiConverterBoolean.check_lower(value.fatal)
            _UniffiFfiConverterBoolean.check_lower(value.retriable)
            return

    @staticmethod
    def write(value, buf):
        if isinstance(value, FfiError.Protocol):
            buf.write_i32(1)
            _UniffiFfiConverterString.write(value.code, buf)
            _UniffiFfiConverterString.write(value.message, buf)
            _UniffiFfiConverterBoolean.write(value.fatal, buf)
            _UniffiFfiConverterBoolean.write(value.retriable, buf)






class FrameType(enum.Enum):
    """
    Frame types. `0x06 rekey` is the control frame that starts a new generation.
"""
    
    HANDSHAKE = 0
    """
    `0x01` — carries a raw Noise handshake message, plaintext, counter = 0.
"""
    
    RPC = 1
    """
    `0x02` — JSON-RPC request/response.
"""
    
    EVENT = 2
    """
    `0x03` — core → module event.
"""
    
    HEARTBEAT = 3
    """
    `0x04` — keepalive.
"""
    
    CLOSE = 4
    """
    `0x05` — orderly close with a `{code,message}` body.
"""
    
    REKEY = 5
    """
    `0x06` — rekey; body is `{new_generation: u32 BE}`, sealed with the old key.
"""
    


class _UniffiFfiConverterTypeFrameType(_UniffiConverterRustBuffer):
    @staticmethod
    def read(buf):
        variant = buf.read_i32()
        if variant == 1:
            return FrameType.HANDSHAKE
        if variant == 2:
            return FrameType.RPC
        if variant == 3:
            return FrameType.EVENT
        if variant == 4:
            return FrameType.HEARTBEAT
        if variant == 5:
            return FrameType.CLOSE
        if variant == 6:
            return FrameType.REKEY
        raise InternalError("Raw enum value doesn't match any cases")

    @staticmethod
    def check_lower(value):
        if value == FrameType.HANDSHAKE:
            return
        if value == FrameType.RPC:
            return
        if value == FrameType.EVENT:
            return
        if value == FrameType.HEARTBEAT:
            return
        if value == FrameType.CLOSE:
            return
        if value == FrameType.REKEY:
            return
        raise ValueError(value)

    @staticmethod
    def write(value, buf):
        if value == FrameType.HANDSHAKE:
            buf.write_i32(1)
        if value == FrameType.RPC:
            buf.write_i32(2)
        if value == FrameType.EVENT:
            buf.write_i32(3)
        if value == FrameType.HEARTBEAT:
            buf.write_i32(4)
        if value == FrameType.CLOSE:
            buf.write_i32(5)
        if value == FrameType.REKEY:
            buf.write_i32(6)








